{"command":"mkdir -p /tmp/test_ssl_ffi && cd /tmp/test_ssl_ffi
cat << 'EOF' > src/ssl.rs
use std::ffi::c_void;
use std::os::raw::{c_char, c_int, c_long};

#[repr(C)]
pub struct SSL_CTX { _private: [u8; 0] }
#[repr(C)]
pub struct SSL { _private: [u8; 0] }
#[repr(C)]
pub struct SSL_METHOD { _private: [u8; 0] }

#[link(name = "ssl")]
#[link(name = "crypto")]
extern "C" {
    pub fn TLS_client_method() -> *const SSL_METHOD;
    pub fn SSL_CTX_new(method: *const SSL_METHOD) -> *mut SSL_CTX;
    pub fn SSL_CTX_free(ctx: *mut SSL_CTX);
    pub fn SSL_CTX_set_verify(ctx: *mut SSL_CTX, mode: c_int, callback: Option<unsafe extern "C" fn(c_int, *mut c_void) -> c_int>);
    pub fn SSL_new(ctx: *mut SSL_CTX) -> *mut SSL;
    pub fn SSL_free(ssl: *mut SSL);
    pub fn SSL_set_fd(ssl: *mut SSL, fd: c_int) -> c_int;
    pub fn SSL_connect(ssl: *mut SSL) -> c_int;
    pub fn SSL_read(ssl: *mut SSL, buf: *mut c_void, num: c_int) -> c_int;
    pub fn SSL_write(ssl: *mut SSL, buf: *const c_void, num: c_int) -> c_int;
    pub fn SSL_set_tlsext_host_name(ssl: *mut SSL, name: *const c_char) -> c_long;
}

pub struct SslContext(*mut SSL_CTX);
unsafe impl Send for SslContext {}
unsafe impl Sync for SslContext {}

impl SslContext {
    pub fn new(insecure: bool) -> Result<Self, String> {
        unsafe {
            let method = TLS_client_method();
            if method.is_null() { return Err("Failed to get TLS client method".into()); }
            let ctx = SSL_CTX_new(method);
            if ctx.is_null() { return Err("Failed to create SSL_CTX".into()); }
            if insecure {
                SSL_CTX_set_verify(ctx, 0, None); // SSL_VERIFY_NONE = 0
            }
            Ok(SslContext(ctx))
        }
    }
}

impl Drop for SslContext {
    fn drop(&mut self) {
        unsafe { SSL_CTX_free(self.0); }
    }
}
EOF
cat << 'EOF' > src/main.rs
mod ssl;
fn main() {
    let _ctx = ssl::SslContext::new(true).unwrap();
    println!("SSL context initialized successfully!");
}
EOF
