cat << 'EOF' > src/main.rs
use rand::Rng;

fn expand_regex(pattern: &str, max_repeat: usize) -> String {
    let mut rng = rand::thread_rng();
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    let mut result = String::new();

    while i < chars.len() {
        if chars[i] == '[' {
            // Character class
            let mut j = i + 1;
            let mut set_chars = Vec::new();
            while j < chars.len() && chars[j] != ']' {
                if j + 2 < chars.len() && chars[j+1] == '-' {
                    let start = chars[j];
                    let end = chars[j+2];
                    for c in start..=end {
                        set_chars.push(c);
                    }
                    j += 3;
                } else {
                    set_chars.push(chars[j]);
                    j += 1;
                }
            }
            i = if j < chars.len() { j + 1 } else { j };

            // Check for quantifier after ]
            let count = parse_quantifier(&chars, &mut i, max_repeat, &mut rng);
            if !set_chars.is_empty() {
                for _ in 0..count {
                    let idx = rng.gen_range(0..set_chars.len());
                    result.push(set_chars[idx]);
                }
            }
        } else if chars[i] == '(' {
            // Group alternation (opt1|opt2)
            let mut j = i + 1;
            let mut depth = 1;
            let start = j;
            while j < chars.len() && depth > 0 {
                if chars[j] == '(' { depth += 1; }
                else if chars[j] == ')' { depth -= 1; }
                if depth > 0 { j += 1; }
            }
            let group_str: String = chars[start..j].iter().collect();
            i = if j < chars.len() { j + 1 } else { j };

            let opts: Vec<&str> = group_str.split('|').collect();
            let count = parse_quantifier(&chars, &mut i, max_repeat, &mut rng);
            if !opts.is_empty() {
                for _ in 0..count {
                    let chosen = opts[rng.gen_range(0..opts.len())];
