use std::io::{Read, Write};
use std::net::TcpStream;
use std::time::{Duration, Instant};
use url::Url;

fn main() {
    let url_str = "http://127.0.0.1:8915/";

    // Start a server in python
    std::thread::spawn(|| {
        use std::process::Command;
        let _ = Command::new("python3")
            .arg("-c")
            .arg("import http.server, socketserver; server = socketserver.TCPServer(('127.0.0.1', 8915), http.server.SimpleHTTPRequestHandler); server.serve_forever()")
            .status();
    });
    std::thread::sleep(Duration::from_millis(500));

    let url = Url::parse(url_str).unwrap();
    let host = url.host_str().unwrap();
    let port = url.port_or_known_default().unwrap();
    let addr = format!("{}:{}", host, port);

    let t0 = Instant::now();
    let mut stream = TcpStream::connect_timeout(&addr.parse().unwrap(), Duration::from_secs(5)).unwrap();
    let t_connect = Instant::now();

    let req = format!(
        "GET {} HTTP/1.1\r\nHost: {}\r\nUser-Agent: oha/1.12.1\r\nAccept: */*\r\nConnection: close\r\n\r\n",
        url.path(),
        host
    );
    stream.write_all(req.as_bytes()).unwrap();

    let mut response_bytes = Vec::new();
    let mut buf = [0u8; 4096];
    let mut t_headers = None;

    loop {
        match stream.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => {
                if t_headers.is_none() {
                    t_headers = Some(Instant::now());
                }
                response_bytes.extend_from_slice(&buf[..n]);
            }
            Err(_) => break,
        }
    }
    let t_end = Instant::now();

    println!("Total duration: {:?}", t_end - t0);
    println!("Connect duration: {:?}", t_connect - t0);
    println!("Response delay: {:?}", t_headers.unwrap() - t_connect);
    println!("Response length: {} bytes", response_bytes.len());
}
