use rand::Rng;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

#[derive(Clone, Debug)]
pub enum UrlProvider {
    Single(String),
    FromFile(Vec<String>),
    Regex { pattern: String, max_repeat: usize },
}

impl UrlProvider {
    pub fn new(url_str: &str, urls_from_file: bool, rand_regex_url: bool, max_repeat: usize) -> Result<Self, String> {
        if urls_from_file {
            let path = Path::new(url_str);
            let file = File::open(path).map_err(|e| format!("{}", e))?;
            let reader = BufReader::new(file);
            let mut urls = Vec::new();
            for line in reader.lines() {
                let l = line.map_err(|e| format!("{}", e))?;
                let trimmed = l.trim().to_string();
                if !trimmed.is_empty() {
                    urls.push(trimmed);
                }
            }
            if urls.is_empty() {
                return Err("No URLs found in file".into());
            }
            Ok(UrlProvider::FromFile(urls))
        } else if rand_regex_url {
            Ok(UrlProvider::Regex {
                pattern: url_str.to_string(),
                max_repeat,
            })
        } else {
            Ok(UrlProvider::Single(url_str.to_string()))
        }
    }

    pub fn get_url(&self) -> String {
        let mut rng = rand::thread_rng();
        match self {
            UrlProvider::Single(u) => u.clone(),
            UrlProvider::FromFile(list) => {
                let idx = rng.gen_range(0..list.len());
                list[idx].clone()
            }
            UrlProvider::Regex { pattern, max_repeat } => {
                expand_regex(pattern, *max_repeat)
            }
        }
    }
}

pub fn expand_regex(pattern: &str, max_repeat: usize) -> String {
    let mut rng = rand::thread_rng();
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    let mut result = String::new();

    while i < chars.len() {
        if chars[i] == '[' {
            let mut j = i + 1;
            let mut set_chars = Vec::new();
            while j < chars.len() && chars[j] != ']' {
                if j + 2 < chars.len() && chars[j + 1] == '-' {
                    let start = chars[j];
                    let end = chars[j + 2];
                    for c in start..=end {
                        set_chars.push(c);
                    }
                    j += 3;
                } else {
                    set_chars.push(chars[j]);
                    j += 1;
                }
            }
            i = if j < chars.len() { j + 1 } else { j };

            let count = parse_quantifier(&chars, &mut i, max_repeat, &mut rng);
            if !set_chars.is_empty() {
                for _ in 0..count {
                    let idx = rng.gen_range(0..set_chars.len());
                    result.push(set_chars[idx]);
                }
            }
        } else if chars[i] == '(' {
            let mut j = i + 1;
            let mut depth = 1;
            let start = j;
            while j < chars.len() && depth > 0 {
                if chars[j] == '(' {
                    depth += 1;
                } else if chars[j] == ')' {
                    depth -= 1;
                }
                if depth > 0 {
                    j += 1;
                }
            }
            let group_str: String = chars[start..j].iter().collect();
            i = if j < chars.len() { j + 1 } else { j };

            let opts: Vec<&str> = group_str.split('|').collect();
            let count = parse_quantifier(&chars, &mut i, max_repeat, &mut rng);
            if !opts.is_empty() {
                for _ in 0..count {
                    let chosen = opts[rng.gen_range(0..opts.len())];
                    result.push_str(&expand_regex(chosen, max_repeat));
                }
            }
        } else if chars[i] == '\\' && i + 1 < chars.len() {
            let next_char = chars[i + 1];
            i += 2;
            let count = parse_quantifier(&chars, &mut i, max_repeat, &mut rng);
            for _ in 0..count {
                result.push(next_char);
            }
        } else {
            let ch = chars[i];
            i += 1;
            let count = parse_quantifier(&chars, &mut i, max_repeat, &mut rng);
            for _ in 0..count {
                result.push(ch);
            }
        }
    }
    result
}

fn parse_quantifier(chars: &[char], i: &mut usize, max_repeat: usize, rng: &mut impl Rng) -> usize {
    if *i >= chars.len() {
        return 1;
    }
    match chars[*i] {
        '{' => {
            let mut j = *i + 1;
            while j < chars.len() && chars[j] != '}' {
                j += 1;
            }
            let spec: String = chars[*i + 1..j].iter().collect();
            *i = if j < chars.len() { j + 1 } else { j };
            if let Ok(exact) = spec.parse::<usize>() {
                exact
            } else if spec.contains(',') {
                let parts: Vec<&str> = spec.split(',').collect();
                let min = parts[0].parse::<usize>().unwrap_or(0);
                let max = parts
                    .get(1)
                    .and_then(|s| s.parse::<usize>().ok())
                    .unwrap_or(min + max_repeat);
                rng.gen_range(min..=max)
            } else {
                1
            }
        }
        '*' => {
            *i += 1;
            rng.gen_range(0..=max_repeat)
        }
        '+' => {
            *i += 1;
            rng.gen_range(1..=max_repeat)
        }
        '?' => {
            *i += 1;
            rng.gen_range(0..=1)
        }
        _ => 1,
    }
}
EOF

