{"command":"cat << 'EOF' > src/ssl.rs
use std::ffi::CString;
use std::os::raw::{c_int, c_long, c_void};

#[repr(C)]
pub struct SSL_CTX {
    _private: [u8; 0],
}
#[repr(C)]
pub struct SSL {
    _private: [u8; 0],
}
#[repr(C)]
pub struct SSL_METHOD {
    _private: [u8; 0],
}

const SSL_CTRL_SET_TLSEXT_HOSTNAME: c_int = 55;
const TLSEXT_NAMETYPE_HOST_NAME: c_long = 0;

#[link(name = "ssl")]
#[link(name = "crypto")]
extern "C" {
    pub fn TLS_client_method() -> *const SSL_METHOD;
    pub fn SSL_CTX_new(method: *const SSL_METHOD) -> *mut SSL_CTX;
    pub fn SSL_CTX_free(ctx: *mut SSL_CTX);
    pub fn SSL_CTX_set_verify(
        ctx: *mut SSL_CTX,
        mode: c_int,
        callback: Option<unsafe extern "C" fn(c_int, *mut c_void) -> c_int>,
    );
    pub fn SSL_new(ctx: *mut SSL_CTX) -> *mut SSL;
    pub fn SSL_free(ssl: *mut SSL);
    pub fn SSL_set_fd(ssl: *mut SSL, fd: c_int) -> c_int;
    pub fn SSL_connect(ssl: *mut SSL) -> c_int;
    pub fn SSL_read(ssl: *mut SSL, buf: *mut c_void, num: c_int) -> c_int;
    pub fn SSL_write(ssl: *mut SSL, buf: *const c_void, num: c_int) -> c_int;
    pub fn SSL_ctrl(ssl: *mut SSL, cmd: c_int, larg: c_long, parg: *mut c_void) -> c_long;
}

pub struct SslContext(*mut SSL_CTX);
unsafe impl Send for SslContext {}
unsafe impl Sync for SslContext {}

impl SslContext {
    pub fn new(insecure: bool) -> Result<Self, String> {
        unsafe {
            let method = TLS_client_method();
            if method.is_null() {
                return Err("Failed to get TLS client method".into());
            }
            let ctx = SSL_CTX_new(method);
            if ctx.is_null() {
                return Err("Failed to create SSL_CTX".into());
            }
            if insecure {
                SSL_CTX_set_verify(ctx, 0, None);
            }
            Ok(SslContext(ctx))
        }
    }
}

impl Drop for SslContext {
    fn drop(&mut self) {
        unsafe {
            SSL_CTX_free(self.0);
        }
    }
}

pub struct SslStream(*mut SSL);

impl SslStream {
    pub fn new(ctx: &SslContext, fd: c_int, hostname: &str) -> Result<Self, String> {
        unsafe {
            let ssl = SSL_new(ctx.0);
            if ssl.is_null() {
                return Err("SSL_new failed".into());
            }
            SSL_set_fd(ssl, fd);
            if let Ok(c_host) = CString::new(hostname) {
                SSL_ctrl(
                    ssl,
                    SSL_CTRL_SET_TLSEXT_HOSTNAME,
                    TLSEXT_NAMETYPE_HOST_NAME,
                    c_host.as_ptr() as *mut c_void,
                );
            }
            let ret = SSL_connect(ssl);
            if ret <= 0 {
                SSL_free(ssl);
                return Err("SSL_connect failed".into());
            }
            Ok(SslStream(ssl))
        }
    }

    pub fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        unsafe {
            let n = SSL_read(self.0, buf.as_mut_ptr() as *mut c_void, buf.len() as c_int);
            if n > 0 {
                Ok(n as usize)
            } else if n == 0 {
                Ok(0)
            } else {
                Err(std::io::Error::new(
                    std::io::ErrorKind::ConnectionAborted,
                    "SSL read error",
                ))
            }
        }
    }

    pub fn write_all(&mut self, mut buf: &[u8]) -> std::io::Result<()> {
        unsafe {
            while !buf.is_empty() {
                let n = SSL_write(self.0, buf.as_ptr() as *const c_void, buf.len() as c_int);
                if n <= 0 {
                    return Err(std::io::Error::new(
                        std::io::ErrorKind::WriteZero,
                        "SSL write error",
                    ));
                }
                buf = &buf[n as usize..];
            }
            Ok(())
        }
    }
}

impl Drop for SslStream {
    fn drop(&mut self) {
        unsafe {
            SSL_free(self.0);
        }
    }
}
EOF"}

