pub struct HttpClient {
    pub opts: Arc<Opts>,
    pub ssl_ctx: Option<Arc<SslContext>>,
    pub cached_addr: Option<SocketAddr>,
}

impl HttpClient {
    pub fn new(opts: Arc<Opts>) -> Result<Self, String> {
        let ssl_ctx = if opts.url.starts_with("https://") || opts.insecure {
            Some(Arc::new(SslContext::new(opts.insecure)?))
        } else {
            None
        };

        let cached_addr = if !opts.no_pre_lookup && !opts.url.is_empty() {
            if let Ok(parsed) = Url::parse(&opts.url) {
                let host = parsed.host_str().unwrap_or("localhost");
                let port = parsed.port_or_known_default().unwrap_or(80);
                format!("{}:{}", host, port)
                    .to_socket_addrs()
                    .ok()
                    .and_then(|mut addrs| addrs.next())
            } else {
                None
            }
        } else {
            None
        };

        Ok(HttpClient {
            opts,
            ssl_ctx,
            cached_addr,
        })
    }

    pub fn execute(
        &mut self,
        target_url: &str,
        conn: &mut Option<ConnectionStream>,
        bench_start: Instant,
    ) -> RequestResult {
        let start_time = Instant::now();
        let start_offset = start_time.saturating_duration_since(bench_start);

        let parsed_url = match Url::parse(target_url) {
            Ok(u) => u,
            Err(e) => {
                let dur = start_time.elapsed();
                return RequestResult {
                    start_time,
                    start_offset,
                    dns_lookup_duration: Duration::ZERO,
                    dns_dialup_duration: Duration::ZERO,
                    response_delay: Duration::ZERO,
                    request_duration: dur,
                    bytes: 0,
                    status: Err(format!("relative URL without a base")),
                };
            }
        };

        let is_https = parsed_url.scheme() == "https";
        let host = parsed_url.host_str().unwrap_or("localhost").to_string();
        let port = parsed_url.port_or_known_default().unwrap_or(if is_https { 443 } else { 80 });

        let mut dns_lookup_duration = Duration::ZERO;
        let mut dns_dialup_duration = Duration::ZERO;

        let is_new_conn = conn.is_none();

        if conn.is_none() {
            let t_dns_start = Instant::now();
            let addr = if let Some(addr) = self.cached_addr {
                addr
            } else {
                let addr_str = format!("{}:{}", host, port);
                match addr_str.to_socket_addrs().ok().and_then(|mut a| a.next()) {
                    Some(a) => a,
                    None => {
                        let dur = start_time.elapsed();
                        return RequestResult {
                            start_time,
                            start_offset,
                            dns_lookup_duration: t_dns_start.elapsed(),
                            dns_dialup_duration: t_dns_start.elapsed(),
                            response_delay: Duration::ZERO,
                            request_duration: dur,
                            bytes: 0,
                            status: Err(format!("Could not resolve host {}", host)),
                        };
                    }
                }
            };
            dns_lookup_duration = t_dns_start.elapsed();

            let tcp = match TcpStream::connect_timeout(&addr, self.opts.connect_timeout) {
                Ok(s) => s,
                Err(e) => {
