use crate::cli::Opts;
use crate::client::{HttpClient, RequestResult};
use crate::url_provider::UrlProvider;
use crossbeam_channel::{unbounded, Receiver};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

pub struct Runner {
    opts: Arc<Opts>,
    url_provider: UrlProvider,
}

impl Runner {
    pub fn new(opts: Arc<Opts>, url_provider: UrlProvider) -> Self {
        Runner { opts, url_provider }
    }

    pub fn run(&self) -> (Instant, Receiver<RequestResult>) {
        let (tx, rx) = unbounded();
        let bench_start = Instant::now();

        let num_workers = self.opts.n_connections;
        let total_requests = self.opts.n_requests;
        let has_duration = self.opts.duration.is_some();
        let deadline = self.opts.duration.map(|d| bench_start + d);

        let remaining_requests = if !has_duration {
            Some(Arc::new(AtomicUsize::new(total_requests)))
        } else {
            None
        };

        let qps_delay = self.opts.query_per_second.map(|q| {
            if q > 0.0 {
                Duration::from_secs_f64(1.0 / q)
            } else {
                Duration::ZERO
            }
        });

        let qps_last_sent = Arc::new(std::sync::Mutex::new(bench_start));

        let mut handles = Vec::new();

        for _ in 0..num_workers {
            let opts = self.opts.clone();
            let url_prov = self.url_provider.clone();
            let tx = tx.clone();
            let remaining_reqs = remaining_requests.clone();
            let qps_last_sent = qps_last_sent.clone();

            let handle = thread::spawn(move || {
                let mut client = match HttpClient::new(opts.clone()) {
                    Ok(c) => c,
                    Err(_) => return,
                };
                let mut conn = None;
                let mut req_counter = 0;

                loop {
                    if let Some(dl) = deadline {
                        if Instant::now() >= dl {
                            break;
                        }
                    }

                    if let Some(rem) = &remaining_reqs {
                        let cur = rem.fetch_update(Ordering::SeqCst, Ordering::SeqCst, |val| {
                            if val > 0 {
                                Some(val - 1)
                            } else {
                                None
                            }
                        });
                        if cur.is_err() {
                            break;
                        }
                    }

                    if let Some(delay) = qps_delay {
                        let mut last = qps_last_sent.lock().unwrap();
                        let target = *last + delay;
                        let now = Instant::now();
                        if target > now {
                            thread::sleep(target - now);
                            *last = target;
                        } else {
                            *last = now;
                        }
                    } else if let Some(bd) = opts.burst_delay {
                        req_counter += 1;
                        if req_counter % opts.burst_rate == 0 {
                            thread::sleep(bd);
                        }
                    }

                    let url = url_prov.get_url();
                    let result = client.execute(&url, &mut conn, bench_start);

                    if tx.send(result).is_err() {
                        break;
                    }
                }
            });
            handles.push(handle);
        }

        drop(tx);

        for handle in handles {
            let _ = handle.join();
        }

        (bench_start, rx)
    }
}
EOF"}

