use crate::client::RequestResult;
use serde::Serialize;
use std::collections::BTreeMap;
use std::time::Duration;

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Summary {
    pub success_rate: f64,
    pub total: f64,
    pub slowest: Option<f64>,
    pub fastest: Option<f64>,
    pub average: Option<f64>,
    pub requests_per_sec: f64,
    pub total_data: u64,
    pub size_per_request: Option<u64>,
    pub size_per_sec: f64,
}

#[derive(Debug, Clone, Serialize, Default)]
pub struct Percentiles {
    pub p10: Option<f64>,
    pub p25: Option<f64>,
    pub p50: Option<f64>,
    pub p75: Option<f64>,
    pub p90: Option<f64>,
    pub p95: Option<f64>,
    pub p99: Option<f64>,
    #[serde(rename = "p99.9")]
    pub p99_9: Option<f64>,
    #[serde(rename = "p99.99")]
    pub p99_99: Option<f64>,
}

impl Percentiles {
    pub fn default_null() -> Self {
        Percentiles {
            p10: None,
            p25: None,
            p50: None,
            p75: None,
            p90: None,
            p95: None,
            p99: None,
            p99_9: None,
            p99_99: None,
        }
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct RpsStats {
    pub mean: Option<f64>,
    pub stddev: Option<f64>,
    pub max: Option<f64>,
    pub min: Option<f64>,
    pub percentiles: Percentiles,
}

#[derive(Debug, Clone, Serialize)]
pub struct StatDetail {
    pub average: Option<f64>,
    pub fastest: Option<f64>,
    pub slowest: Option<f64>,
}

#[derive(Debug, Clone, Serialize)]
pub struct Details {
    #[serde(rename = "DNSDialup")]
    pub dns_dialup: StatDetail,
    #[serde(rename = "DNSLookup")]
    pub dns_lookup: StatDetail,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct BenchmarkReport {
    pub summary: Summary,
    pub response_time_histogram: BTreeMap<String, usize>,
    pub latency_percentiles: Percentiles,

    #[serde(skip_serializing_if = "Option::is_none")]
    pub response_time_histogram_successful: Option<BTreeMap<String, usize>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub latency_percentiles_successful: Option<Percentiles>,

    #[serde(skip_serializing_if = "Option::is_none")]
    pub response_time_histogram_not_successful: Option<BTreeMap<String, usize>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub latency_percentiles_not_successful: Option<Percentiles>,

    pub rps: RpsStats,
    pub details: Details,
    pub status_code_distribution: BTreeMap<String, usize>,
    pub error_distribution: BTreeMap<String, usize>,
}

pub fn compute_stats(
    results: &[RequestResult],
    total_elapsed: Duration,
    include_breakdown: bool,
) -> BenchmarkReport {
    let total_secs = total_elapsed.as_secs_f64();

    let mut successful_durations: Vec<f64> = Vec::new();
    let mut successful_2xx_durations: Vec<f64> = Vec::new();
    let mut successful_non2xx_durations: Vec<f64> = Vec::new();

    let mut dns_dialup_durations: Vec<f64> = Vec::new();
    let mut dns_lookup_durations: Vec<f64> = Vec::new();

    let mut total_bytes: u64 = 0;
    let mut status_codes: BTreeMap<String, usize> = BTreeMap::new();
    let mut errors: BTreeMap<String, usize> = BTreeMap::new();

    let total_count = results.len();
    let mut ok_count = 0;

    for r in results {
        match &r.status {
            Ok(code) => {
                ok_count += 1;
                let dur = r.request_duration.as_secs_f64();
                successful_durations.push(dur);

                if *code >= 200 && *code < 300 {
                    successful_2xx_durations.push(dur);
                } else {
                    successful_non2xx_durations.push(dur);
                }

                *status_codes.entry(code.to_string()).or_insert(0) += 1;
