            Some(dns_dialup_durations.iter().sum::<f64>() / dns_dialup_durations.len() as f64)
        } else {
            None
        },
        fastest: dns_dialup_durations.iter().cloned().reduce(f64::min),
        slowest: dns_dialup_durations.iter().cloned().reduce(f64::max),
    };

    let dns_lookup = StatDetail {
        average: if !dns_lookup_durations.is_empty() {
            Some(dns_lookup_durations.iter().sum::<f64>() / dns_lookup_durations.len() as f64)
        } else {
            None
        },
        fastest: dns_lookup_durations.iter().cloned().reduce(f64::min),
        slowest: dns_lookup_durations.iter().cloned().reduce(f64::max),
    };

    let rps_val = if total_secs > 0.0 {
        Some(total_count as f64 / total_secs)
    } else {
        None
    };

    let rps = RpsStats {
        mean: rps_val,
        stddev: None,
        max: rps_val,
        min: rps_val,
        percentiles: if let Some(v) = rps_val {
            Percentiles {
                p10: Some(v),
                p25: Some(v),
                p50: Some(v),
                p75: Some(v),
                p90: Some(v),
                p95: Some(v),
                p99: Some(v),
                p99_9: Some(v),
                p99_99: Some(v),
            }
        } else {
            Percentiles::default_null()
        },
    };

    BenchmarkReport {
        summary,
        response_time_histogram,
        latency_percentiles,
        response_time_histogram_successful: hist_2xx,
        latency_percentiles_successful: perc_2xx,
        response_time_histogram_not_successful: hist_non2xx,
        latency_percentiles_not_successful: perc_non2xx,
        rps,
        details: Details {
            dns_dialup,
            dns_lookup,
        },
        status_code_distribution: status_codes,
        error_distribution: errors,
    }
}

pub fn compute_percentiles(durations: &[f64]) -> Percentiles {
    if durations.is_empty() {
        return Percentiles::default_null();
    }
    let n = durations.len();
    let get_p = |p: f64| -> Option<f64> {
        if n == 1 {
            return Some(durations[0]);
        }
        let rank = (n - 1) as f64 * p;
        let lower = rank.floor() as usize;
        let upper = rank.ceil() as usize;
        let fract = rank - lower as f64;
        if lower == upper {
            Some(durations[lower])
        } else {
            Some(durations[lower] + fract * (durations[upper] - durations[lower]))
        }
    };
    Percentiles {
        p10: get_p(0.10),
        p25: get_p(0.25),
        p50: get_p(0.50),
        p75: get_p(0.75),
        p90: get_p(0.90),
        p95: get_p(0.95),
        p99: get_p(0.99),
        p99_9: get_p(0.999),
        p99_99: get_p(0.9999),
    }
}

pub fn compute_histogram(durations: &[f64]) -> BTreeMap<String, usize> {
    let mut map = BTreeMap::new();
    if durations.is_empty() {
        map.insert("NaN".to_string(), 0);
        return map;
    }
    let fastest = durations[0];
    let slowest = durations[durations.len() - 1];

    if (slowest - fastest).abs() < 1e-12 {
        map.insert(format!("{}", fastest), durations.len());
        return map;
    }

    let step = (slowest - fastest) / 10.0;
    let mut counts = [0usize; 11];

    for &d in durations {
        let bin = (((d - fastest) / step).floor() as usize).min(10);
        counts[bin] += 1;
    }

    for i in 0..11 {
        let bin_bound = fastest + i as f64 * step;
        map.insert(format!("{}", bin_bound), counts[i]);
    }
    map
}
EOF"}

