use crate::client::RequestResult;
use crate::stats::BenchmarkReport;

pub fn format_output(
    report: &BenchmarkReport,
    results: &[RequestResult],
    format_type: &str,
    user_unit: Option<&str>,
) -> String {
    match format_type {
        "quiet" => "".to_string(),
        "json" => serde_json::to_string_pretty(report).unwrap_or_default(),
        "csv" => format_csv(results),
        _ => format_text(report, user_unit),
    }
}

fn format_csv(results: &[RequestResult]) -> String {
    let mut out = String::from("request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status\n");
    for r in results {
        if let Ok(code) = &r.status {
            out.push_str(&format!(
                "{:.9},{:.9},{:.9},{:.9},{:.9},{},{}\n",
                r.start_offset.as_secs_f64(),
                r.dns_lookup_duration.as_secs_f64(),
                r.dns_dialup_duration.as_secs_f64(),
                r.response_delay.as_secs_f64(),
                r.request_duration.as_secs_f64(),
                r.bytes,
                code
            ));
        }
    }
    out
}

fn select_time_unit(report: &BenchmarkReport, user_unit: Option<&str>) -> String {
    if let Some(u) = user_unit {
        return u.to_string();
    }
    if let Some(avg) = report.summary.average {
        if avg < 1e-6 {
            "ns".to_string()
        } else if avg < 1e-3 {
            "us".to_string()
        } else if avg < 1.0 {
            "ms".to_string()
        } else if avg < 60.0 {
            "s".to_string()
        } else if avg < 3600.0 {
            "m".to_string()
        } else {
            "h".to_string()
        }
    } else {
        "ns".to_string()
    }
}

fn format_dur(secs: Option<f64>, unit: &str) -> String {
    match secs {
        Some(s) if s.is_finite() => match unit {
            "ns" => format!("{:.4} ns", s * 1e9),
            "us" => format!("{:.4} us", s * 1e6),
            "ms" => format!("{:.4} ms", s * 1e3),
            "s" => format!("{:.4} s", s),
            "m" => format!("{:.4} m", s / 60.0),
            "h" => format!("{:.4} h", s / 3600.0),
            _ => format!("{:.4} s", s),
        },
        Some(s) if s.is_infinite() && s.is_sign_positive() => format!("inf {}", unit),
        Some(s) if s.is_infinite() && s.is_sign_negative() => format!("-inf {}", unit),
        _ => format!("NaN {}", unit),
    }
}

fn format_bytes_val(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:.2} KiB", bytes as f64 / 1024.0)
    } else if bytes < 1024 * 1024 * 1024 {
        format!("{:.2} MiB", bytes as f64 / (1024.0 * 1024.0))
    } else {
        format!("{:.2} GiB", bytes as f64 / (1024.0 * 1024.0 * 1024.0))
    }
}

