        &report.latency_percentiles_not_successful,
    ) {
        out.push_str("Response time histogram (4xx + 5xx only):\n");
        render_histogram_text(&mut out, h_not_successful, &unit);
        out.push_str("\n");

        out.push_str("Response time distribution (4xx + 5xx only):\n");
        render_percentiles_text(&mut out, p_not_successful, &unit);
        out.push_str("\n\n");
    }

    out.push_str("Details (average, fastest, slowest):\n");
    out.push_str(&format!(
        "  DNS+dialup:\t{}, {}, {}\n",
