        for (err_msg, count) in &report.error_distribution {
            out.push_str(&format!("  [{}] {}\n", count, err_msg));
        }
    }

    out
}

fn render_histogram_text(out: &mut String, hist: &std::collections::BTreeMap<String, usize>, unit: &str) {
    let max_count = hist.values().cloned().max().unwrap_or(0);

    for (key, &count) in hist {
        let val_sec: Option<f64> = key.parse().ok();
        let dur_str = format_dur(val_sec, unit);

        let bar_len = if max_count > 0 {
