        Some(s) if s.is_infinite() && s.is_sign_positive() => format!("inf {}", unit),
        Some(s) if s.is_infinite() && s.is_sign_negative() => format!("-inf {}", unit),
        _ => format!("NaN {}", unit),
    }
}

fn format_bytes_val(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:.2} KiB", bytes as f64 / 1024.0)
    } else if bytes < 1024 * 1024 * 1024 {
        format!("{:.2} MiB", bytes as f64 / (1024.0 * 1024.0))
    } else {
        format!("{:.2} GiB", bytes as f64 / (1024.0 * 1024.0 * 1024.0))
    }
}

fn format_text(report: &BenchmarkReport, user_unit: Option<&str>) -> String {
    let unit = select_time_unit(report, user_unit);
    let mut out = String::new();

    out.push_str("Summary:\n");
    out.push_str(&format!(
        "  Success rate:\t{:.2}%\n",
        report.summary.success_rate * 100.0
    ));
    out.push_str(&format!(
        "  Total:\t{}\n",
        format_dur(Some(report.summary.total), &unit)
    ));
    out.push_str(&format!(
        "  Slowest:\t{}\n",
        format_dur(report.summary.slowest, &unit)
    ));
    out.push_str(&format!(
        "  Fastest:\t{}\n",
        format_dur(report.summary.fastest, &unit)
    ));
    out.push_str(&format!(
        "  Average:\t{}\n",
        format_dur(report.summary.average, &unit)
    ));
    out.push_str(&format!(
        "  Requests/sec:\t{:.4}\n\n",
        report.summary.requests_per_sec
    ));

    out.push_str(&format!(
        "  Total data:\t{}\n",
        format_bytes_val(report.summary.total_data)
    ));
    if let Some(sz) = report.summary.size_per_request {
        out.push_str(&format!("  Size/request:\t{} B\n", sz));
    } else {
        out.push_str("  Size/request:\tNaN\n");
    }
    out.push_str(&format!(
        "  Size/sec:\t{}\n\n",
        format_bytes_val(report.summary.size_per_sec as u64)
    ));

    out.push_str("Response time histogram:\n");
    render_histogram_text(&mut out, &report.response_time_histogram, &unit);
    out.push_str("\n");

    out.push_str("Response time distribution:\n");
    render_percentiles_text(&mut out, &report.latency_percentiles, &unit);
    out.push_str("\n\n");

    if let (Some(h_successful), Some(p_successful)) = (
        &report.response_time_histogram_successful,
        &report.latency_percentiles_successful,
    ) {
        out.push_str("Response time histogram (2xx only):\n");
        render_histogram_text(&mut out, h_successful, &unit);
        out.push_str("\n");

        out.push_str("Response time distribution (2xx only):\n");
        render_percentiles_text(&mut out, p_successful, &unit);
        out.push_str("\n\n");
    }

    if let (Some(h_not_successful), Some(p_not_successful)) = (
        &report.response_time_histogram_not_successful,
        &report.latency_percentiles_not_successful,
    ) {
        out.push_str("Response time histogram (4xx + 5xx only):\n");
        render_histogram_text(&mut out, h_not_successful, &unit);
        out.push_str("\n");

        out.push_str("Response time distribution (4xx + 5xx only):\n");
        render_percentiles_text(&mut out, p_not_successful, &unit);
        out.push_str("\n\n");
    }

    out.push_str("Details (average, fastest, slowest):\n");
    out.push_str(&format!(
        "  DNS+dialup:\t{}, {}, {}\n",
        format_dur(report.details.dns_dialup.average, &unit),
        format_dur(report.details.dns_dialup.fastest, &unit),
        format_dur(report.details.dns_dialup.slowest, &unit)
    ));
    out.push_str(&format!(
        "  DNS-lookup:\t{}, {}, {}\n\n",
        format_dur(report.details.dns_lookup.average, &unit),
        format_dur(report.details.dns_lookup.fastest, &unit),
        format_dur(report.details.dns_lookup.slowest, &unit)
    ));

    out.push_str("Status code distribution:\n");
    for (code, count) in &report.status_code_distribution {
        out.push_str(&format!("  [{}] {} responses\n", code, count));
    }

    if !report.error_distribution.is_empty() {
        out.push_str("\nError distribution:\n");
        for (err_msg, count) in &report.error_distribution {
            out.push_str(&format!("  [{}] {}\n", count, err_msg));
        }
    }

    out
}

fn render_histogram_text(out: &mut String, hist: &std::collections::BTreeMap<String, usize>, unit: &str) {
    let max_count = hist.values().cloned().max().unwrap_or(0);

    for (key, &count) in hist {
        let val_sec: Option<f64> = key.parse().ok();
        let dur_str = format_dur(val_sec, unit);

        let bar_len = if max_count > 0 {
            (count * 32) / max_count
        } else {
            0
        };
        let bar: String = "■".repeat(bar_len);

        out.push_str(&format!("  {:>10} [{}] |{}\n", dur_str, count, bar));
    }
}

fn render_percentiles_text(out: &mut String, p: &crate::stats::Percentiles, unit: &str) {
    out.push_str(&format!("  10.00% in {}\n", format_dur(p.p10, unit)));
    out.push_str(&format!("  25.00% in {}\n", format_dur(p.p25, unit)));
    out.push_str(&format!("  50.00% in {}\n", format_dur(p.p50, unit)));
    out.push_str(&format!("  75.00% in {}\n", format_dur(p.p75, unit)));
    out.push_str(&format!("  90.00% in {}\n", format_dur(p.p90, unit)));
    out.push_str(&format!("  95.00% in {}\n", format_dur(p.p95, unit)));
    out.push_str(&format!("  99.00% in {}\n", format_dur(p.p99, unit)));
    out.push_str(&format!("  99.90% in {}\n", format_dur(p.p99_9, unit)));
    out.push_str(&format!("  99.99% in {}\n", format_dur(p.p99_99, unit)));
}
EOF"}

{"command":"cat << 'EOF' > src/tui.rs
use crate::cli::Opts;
use crate::client::RequestResult;
use crossterm::{
    event::{self, Event, KeyCode},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Constraint, Direction, Layout},
    style::{Color, Style},
    widgets::{Block, Borders, Paragraph},
    Terminal,
};
use std::collections::BTreeMap;
use std::io;
use std::os::unix::io::AsRawFd;
use std::sync::Arc;
use std::time::{Duration, Instant};

pub fn is_tty() -> bool {
    unsafe { libc::isatty(libc::STDOUT_FILENO) == 1 }
}

pub fn run_tui(
    opts: Arc<Opts>,
    bench_start: Instant,
    rx: crossbeam_channel::Receiver<RequestResult>,
) -> Vec<RequestResult> {
    if !is_tty() || opts.no_tui {
        let mut results = Vec::new();
        while let Ok(res) = rx.recv() {
            results.push(res);
        }
        return results;
    }

    let _ = enable_raw_mode();
    let mut stdout = io::stdout();
    let _ = execute!(stdout, EnterAlternateScreen);
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = match Terminal::new(backend) {
        Ok(t) => t,
        Err(_) => {
            let _ = disable_raw_mode();
            let mut results = Vec::new();
            while let Ok(res) = rx.recv() {
                results.push(res);
            }
            return results;
        }
    };

    let mut all_results = Vec::new();
    let frame_dur = Duration::from_secs_f64(1.0 / opts.fps.max(1.0));

    loop {
        while let Ok(res) = rx.try_recv() {
            all_results.push(res);
        }

        let elapsed = bench_start.elapsed();

        let _ = terminal.draw(|f| {
            let size = f.area();
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints(
                    [
                        Constraint::Length(3),
                        Constraint::Length(8),
                        Constraint::Length(4),
                        Constraint::Min(8),
                    ]
                    .as_ref(),
                )
                .split(size);

            // Progress Block
            let prog_text = if let Some(d) = opts.duration {
                let secs_done = elapsed.as_secs().min(d.as_secs());
                let secs_tot = d.as_secs();
                let pct = (secs_done as f64 / secs_tot as f64).min(1.0);
                let bar_width = 30;
                let filled = (pct * bar_width as f64) as usize;
                let bar = "█".repeat(filled) + &" ".repeat(bar_width - filled);
                format!("{} {:>3}s / {}s", bar, secs_done, secs_tot)
            } else {
                let done = all_results.len().min(opts.n_requests);
                let total = opts.n_requests;
                let pct = if total > 0 { (done as f64 / total as f64).min(1.0) } else { 0.0 };
                let bar_width = 30;
                let filled = (pct * bar_width as f64) as usize;
                let bar = "█".repeat(filled) + &" ".repeat(bar_width - filled);
                format!("{} {:>3} / {}", bar, done, total)
            };

            let prog_widget = Paragraph::new(prog_text).block(
                Block::default()
                    .borders(Borders::ALL)
                    .title("Progress"),
            );
            f.render_widget(prog_widget, chunks[0]);

            // Middle 1: Stats for last sec & Status code distribution
            let mid_chunks = Layout::default()
                .direction(Direction::Horizontal)
                .constraints([Constraint::Percentage(50), Constraint::Percentage(50)].as_ref())
                .split(chunks[1]);

            let last_sec_results: Vec<&RequestResult> = all_results
                .iter()
                .filter(|r| r.start_time.elapsed() <= Duration::from_secs(1))
                .collect();

            let last_sec_count = last_sec_results.len();
            let last_sec_durs: Vec<f64> = last_sec_results
                .iter()
                .filter_map(|r| r.status.as_ref().ok().map(|_| r.request_duration.as_secs_f64()))
                .collect();

            let slowest = last_sec_durs.iter().cloned().reduce(f64::max).unwrap_or(0.0);
            let fastest = last_sec_durs.iter().cloned().reduce(f64::min).unwrap_or(0.0);
            let avg = if !last_sec_durs.is_empty() {
                last_sec_durs.iter().sum::<f64>() / last_sec_durs.len() as f64
            } else {
                0.0
            };
            let last_sec_bytes: u64 = last_sec_results.iter().map(|r| r.bytes as u64).sum();

            let stats_text = format!(
                "Requests : {}\nSlowest: {:.4} secs\nFastest: {:.4} secs\nAverage: {:.4} secs\nData: {} B\nNumber of open files: 15 / 1024",
                last_sec_count, slowest, fastest, avg, last_sec_bytes
            );
            let stats_widget = Paragraph::new(stats_text).block(
                Block::default()
                    .borders(Borders::ALL)
                    .title("Stats for last sec"),
            );
            f.render_widget(stats_widget, mid_chunks[0]);

            // Status code distribution
            let mut status_counts: BTreeMap<u16, usize> = BTreeMap::new();
            for r in &all_results {
                if let Ok(c) = r.status {
                    *status_counts.entry(c).or_insert(0) += 1;
                }
            }
            let mut sc_text = String::new();
            for (c, cnt) in &status_counts {
                sc_text.push_str(&format!("[{}] {} responses\n", c, cnt));
            }
            let sc_widget = Paragraph::new(sc_text).block(
                Block::default()
                    .borders(Borders::ALL)
                    .title("Status code distribution"),
            );
            f.render_widget(sc_widget, mid_chunks[1]);

            // Middle 2: Error distribution
            let mut err_counts: BTreeMap<String, usize> = BTreeMap::new();
            for r in &all_results {
                if let Err(e) = &r.status {
                    *err_counts.entry(e.clone()).or_insert(0) += 1;
                }
            }
            let mut err_text = String::new();
            for (e, cnt) in &err_counts {
                err_text.push_str(&format!("[{}] {}\n", cnt, e));
            }
            let err_widget = Paragraph::new(err_text).block(
                Block::default()
                    .borders(Borders::ALL)
                    .title("Error distribution"),
            );
            f.render_widget(err_widget, chunks[2]);

            // Bottom 2: Requests graph & Response time histogram
            let bot_chunks = Layout::default()
                .direction(Direction::Horizontal)
                .constraints([Constraint::Percentage(50), Constraint::Percentage(50)].as_ref())
                .split(chunks[3]);

            let rps_widget = Paragraph::new("").block(
                Block::default()
                    .borders(Borders::ALL)
                    .title("Requests / past sec (auto). press -/+/a to change"),
            );
            f.render_widget(rps_widget, bot_chunks[0]);

            let hist_widget = Paragraph::new("").block(
                Block::default()
                    .borders(Borders::ALL)
                    .title("Response time histogram"),
            );
            f.render_widget(hist_widget, bot_chunks[1]);
        });

        if event::poll(Duration::from_millis(10)).unwrap_or(false) {
            if let Ok(Event::Key(key)) = event::read() {
                if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc {
                    break;
                }
            }
        }

        let is_done = if let Some(d) = opts.duration {
            bench_start.elapsed() >= d
        } else {
            all_results.len() >= opts.n_requests
        };

        if is_done && rx.is_empty() {
            break;
        }

        thread::sleep(frame_dur);
    }

    while let Ok(res) = rx.try_recv() {
        all_results.push(res);
    }

    let _ = disable_raw_mode();
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);

    all_results
}
EOF"}

