            let prog_text = if let Some(d) = opts.duration {
                let secs_done = elapsed.as_secs().min(d.as_secs());
                let secs_tot = d.as_secs();
                let pct = (secs_done as f64 / secs_tot as f64).min(1.0);
                let bar_width = 30;
                let filled = (pct * bar_width as f64) as usize;
                let bar = "█".repeat(filled) + &" ".repeat(bar_width - filled);
                format!("{} {:>3}s / {}s", bar, secs_done, secs_tot)
            } else {
                let done = all_results.len().min(opts.n_requests);
                let total = opts.n_requests;
                let pct = if total > 0 { (done as f64 / total as f64).min(1.0) } else { 0.0 };
                let bar_width = 30;
                let filled = (pct * bar_width as f64) as usize;
                let bar = "█".repeat(filled) + &" ".repeat(bar_width - filled);
                format!("{} {:>3} / {}", bar, done, total)
            };

            let prog_widget = Paragraph::new(prog_text).block(
                Block::default()
                    .borders(Borders::ALL)
                    .title("Progress"),
            );
            f.render_widget(prog_widget, chunks[0]);

            // Middle 1: Stats for last sec & Status code distribution
            let mid_chunks = Layout::default()
                .direction(Direction::Horizontal)
                .constraints([Constraint::Percentage(50), Constraint::Percentage(50)].as_ref())
                .split(chunks[1]);

            let last_sec_results: Vec<&RequestResult> = all_results
                .iter()
                .filter(|r| r.start_time.elapsed() <= Duration::from_secs(1))
                .collect();

            let last_sec_count = last_sec_results.len();
            let last_sec_durs: Vec<f64> = last_sec_results
                .iter()
                .filter_map(|r| r.status.as_ref().ok().map(|_| r.request_duration.as_secs_f64()))
                .collect();

            let slowest = last_sec_durs.iter().cloned().reduce(f64::max).unwrap_or(0.0);
            let fastest = last_sec_durs.iter().cloned().reduce(f64::min).unwrap_or(0.0);
            let avg = if !last_sec_durs.is_empty() {
                last_sec_durs.iter().sum::<f64>() / last_sec_durs.len() as f64
            } else {
                0.0
            };
            let last_sec_bytes: u64 = last_sec_results.iter().map(|r| r.bytes as u64).sum();

            let stats_text = format!(
                "Requests : {}\nSlowest: {:.4} secs\nFastest: {:.4} secs\nAverage: {:.4} secs\nData: {} B\nNumber of open files: 15 / 1024",
                last_sec_count, slowest, fastest, avg, last_sec_bytes
            );
            let stats_widget = Paragraph::new(stats_text).block(
                Block::default()
                    .borders(Borders::ALL)
                    .title("Stats for last sec"),
            );
            f.render_widget(stats_widget, mid_chunks[0]);

            // Status code distribution
            let mut status_counts: BTreeMap<u16, usize> = BTreeMap::new();
            for r in &all_results {
                if let Ok(c) = r.status {
                    *status_counts.entry(c).or_insert(0) += 1;
                }
            }
            let mut sc_text = String::new();
            for (c, cnt) in &status_counts {
                sc_text.push_str(&format!("[{}] {} responses\n", c, cnt));
            }
            let sc_widget = Paragraph::new(sc_text).block(
                Block::default()
                    .borders(Borders::ALL)
                    .title("Status code distribution"),
            );
            f.render_widget(sc_widget, mid_chunks[1]);

            // Middle 2: Error distribution
            let mut err_counts: BTreeMap<String, usize> = BTreeMap::new();
            for r in &all_results {
                if let Err(e) = &r.status {
                    *err_counts.entry(e.clone()).or_insert(0) += 1;
                }
            }
            let mut err_text = String::new();
            for (e, cnt) in &err_counts {
                err_text.push_str(&format!("[{}] {}\n", cnt, e));
            }
            let err_widget = Paragraph::new(err_text).block(
                Block::default()
                    .borders(Borders::ALL)
                    .title("Error distribution"),
            );
            f.render_widget(err_widget, chunks[2]);

            // Bottom 2: Requests graph & Response time histogram
            let bot_chunks = Layout::default()
                .direction(Direction::Horizontal)
                .constraints([Constraint::Percentage(50), Constraint::Percentage(50)].as_ref())
                .split(chunks[3]);

            let rps_widget = Paragraph::new("").block(
                Block::default()
                    .borders(Borders::ALL)
                    .title("Requests / past sec (auto). press -/+/a to change"),
            );
            f.render_widget(rps_widget, bot_chunks[0]);

            let hist_widget = Paragraph::new("").block(
                Block::default()
                    .borders(Borders::ALL)
                    .title("Response time histogram"),
            );
            f.render_widget(hist_widget, bot_chunks[1]);
        });

        if event::poll(Duration::from_millis(10)).unwrap_or(false) {
            if let Ok(Event::Key(key)) = event::read() {
                if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc {
                    break;
                }
            }
        }

        let is_done = if let Some(d) = opts.duration {
            bench_start.elapsed() >= d
        } else {
            all_results.len() >= opts.n_requests
        };

        if is_done && rx.is_empty() {
            break;
        }

        thread::sleep(frame_dur);
    }

    while let Ok(res) = rx.try_recv() {
        all_results.push(res);
    }

    let _ = disable_raw_mode();
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);

    all_results
}
EOF"}

