mod cli;
mod client;
mod output;
mod runner;
mod ssl;
mod stats;
mod tui;
mod url_provider;

use cli::parse_opts;
use client::{ConnectionStream, HttpClient};
use output::format_output;
use runner::Runner;
use stats::compute_stats;
use std::fs::File;
use std::io::Write;
use std::process;
use std::sync::Arc;
use std::time::Instant;
use url_provider::UrlProvider;

fn main() {
    let opts = match parse_opts() {
        Ok(o) => Arc::new(o),
        Err(e) => {
            eprintln!("{}", e);
            process::exit(2);
        }
    };

    let url_provider = match UrlProvider::new(
        &opts.url,
        opts.urls_from_file,
        opts.rand_regex_url,
        opts.max_repeat,
    ) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    if let Some(dump_n) = opts.dump_urls {
        for _ in 0..dump_n {
            println!("{}", url_provider.get_url());
        }
        process::exit(0);
    }

    if opts.debug {
        let mut client = match HttpClient::new(opts.clone()) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        };
        let target_url = url_provider.get_url();
        let mut conn: Option<ConnectionStream> = None;
        let bench_start = Instant::now();
        let _ = client.execute(&target_url, &mut conn, bench_start);
        process::exit(0);
    }

    let runner = Runner::new(opts.clone(), url_provider);
    let (bench_start, rx) = runner.run();

    let results = tui::run_tui(opts.clone(), bench_start, rx);
    let total_elapsed = bench_start.elapsed();

    let report = compute_stats(&results, total_elapsed, opts.stats_success_breakdown);
    let formatted = format_output(&report, &results, &opts.output_format, opts.time_unit.as_deref());

    if !formatted.is_empty() {
        if let Some(out_path) = &opts.output {
            if let Ok(mut f) = File::create(out_path) {
                let _ = f.write_all(formatted.as_bytes());
            } else {
                eprintln!("Error: Could not write to output file {:?}", out_path);
                process::exit(1);
            }
        } else {
            print!("{}", formatted);
        }
    }
}
EOF"}

