{"command":"cat << 'EOF' > src/client.rs
use crate::cli::Opts;
use crate::ssl::{SslContext, SslStream};
use flate2::read::GzDecoder;
use std::collections::BTreeMap;
use std::fs::File;
use std::io::{Read, Write};
use std::net::{SocketAddr, TcpStream, ToSocketAddrs};
use std::os::unix::io::AsRawFd;
use std::path::Path;
use std::sync::Arc;
use std::time::{Duration, Instant};
use url::Url;

#[derive(Debug, Clone)]
pub struct RequestResult {
    pub start_time: Instant,
    pub start_offset: Duration,
    pub dns_lookup_duration: Duration,
    pub dns_dialup_duration: Duration,
    pub response_delay: Duration,
    pub request_duration: Duration,
    pub bytes: usize,
    pub status: Result<u16, String>,
}

pub enum ConnectionStream {
    Plain(TcpStream),
    Ssl(SslStream, TcpStream),
}

impl ConnectionStream {
    pub fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        match self {
            ConnectionStream::Plain(s) => s.read(buf),
            ConnectionStream::Ssl(s, _) => s.read(buf),
        }
    }

    pub fn write_all(&mut self, buf: &[u8]) -> std::io::Result<()> {
        match self {
            ConnectionStream::Plain(s) => s.write_all(buf),
            ConnectionStream::Ssl(s, _) => s.write_all(buf),
        }
    }

    pub fn set_read_timeout(&mut self, dur: Option<Duration>) -> std::io::Result<()> {
        match self {
            ConnectionStream::Plain(s) => s.set_read_timeout(dur),
            ConnectionStream::Ssl(_, s) => s.set_read_timeout(dur),
        }
    }
}

pub struct HttpClient {
    pub opts: Arc<Opts>,
    pub ssl_ctx: Option<Arc<SslContext>>,
    pub cached_addr: Option<SocketAddr>,
}

impl HttpClient {
    pub fn new(opts: Arc<Opts>) -> Result<Self, String> {
        let ssl_ctx = if opts.url.starts_with("https://") || opts.insecure {
            Some(Arc::new(SslContext::new(opts.insecure)?))
        } else {
            None
        };

        let cached_addr = if !opts.no_pre_lookup && !opts.url.is_empty() {
            if let Ok(parsed) = Url::parse(&opts.url) {
                let host = parsed.host_str().unwrap_or("localhost");
                let port = parsed.port_or_known_default().unwrap_or(80);
                format!("{}:{}", host, port)
                    .to_socket_addrs()
                    .ok()
                    .and_then(|mut addrs| addrs.next())
            } else {
                None
            }
        } else {
            None
        };

        Ok(HttpClient {
            opts,
            ssl_ctx,
            cached_addr,
        })
    }

    pub fn execute(
        &mut self,
        target_url: &str,
        conn: &mut Option<ConnectionStream>,
        bench_start: Instant,
    ) -> RequestResult {
        let start_time = Instant::now();
        let start_offset = start_time.saturating_duration_since(bench_start);

        let parsed_url = match Url::parse(target_url) {
            Ok(u) => u,
            Err(_) => {
                let dur = start_time.elapsed();
                return RequestResult {
                    start_time,
                    start_offset,
                    dns_lookup_duration: Duration::ZERO,
                    dns_dialup_duration: Duration::ZERO,
                    response_delay: Duration::ZERO,
                    request_duration: dur,
                    bytes: 0,
                    status: Err("relative URL without a base".to_string()),
                };
            }
        };

        let is_https = parsed_url.scheme() == "https";
        let host = parsed_url.host_str().unwrap_or("localhost").to_string();
        let port = parsed_url.port_or_known_default().unwrap_or(if is_https { 443 } else { 80 });

        let mut dns_lookup_duration = Duration::ZERO;
        let mut dns_dialup_duration = Duration::ZERO;

        if conn.is_none() {
            let t_dns_start = Instant::now();
            let addr = if let Some(addr) = self.cached_addr {
                addr
            } else {
                let addr_str = format!("{}:{}", host, port);
                match addr_str.to_socket_addrs().ok().and_then(|mut a| a.next()) {
                    Some(a) => a,
                    None => {
                        let dur = start_time.elapsed();
                        return RequestResult {
                            start_time,
                            start_offset,
                            dns_lookup_duration: t_dns_start.elapsed(),
                            dns_dialup_duration: t_dns_start.elapsed(),
                            response_delay: Duration::ZERO,
                            request_duration: dur,
                            bytes: 0,
                            status: Err(format!("Could not resolve host {}", host)),
                        };
                    }
                }
            };
            dns_lookup_duration = t_dns_start.elapsed();

            let tcp = match TcpStream::connect_timeout(&addr, self.opts.connect_timeout) {
                Ok(s) => s,
                Err(e) => {
                    let dur = start_time.elapsed();
                    return RequestResult {
                        start_time,
                        start_offset,
                        dns_lookup_duration,
                        dns_dialup_duration: start_time.elapsed(),
                        response_delay: Duration::ZERO,
                        request_duration: dur,
                        bytes: 0,
                        status: Err(format!("{}", e)),
                    };
                }
            };

            if is_https {
                let ssl_ctx = match &self.ssl_ctx {
                    Some(ctx) => ctx.clone(),
                    None => {
                        let ctx = Arc::new(SslContext::new(self.opts.insecure).unwrap());
                        self.ssl_ctx = Some(ctx.clone());
                        ctx
                    }
                };
                let fd = tcp.as_raw_fd();
                let ssl_stream = match SslStream::new(&ssl_ctx, fd, &host) {
                    Ok(s) => s,
                    Err(e) => {
                        let dur = start_time.elapsed();
                        return RequestResult {
                            start_time,
                            start_offset,
                            dns_lookup_duration,
                            dns_dialup_duration: start_time.elapsed(),
                            response_delay: Duration::ZERO,
                            request_duration: dur,
                            bytes: 0,
                            status: Err(e),
                        };
                    }
                };
                *conn = Some(ConnectionStream::Ssl(ssl_stream, tcp));
            } else {
                *conn = Some(ConnectionStream::Plain(tcp));
            }
            dns_dialup_duration = start_time.elapsed();
        }

        let stream = conn.as_mut().unwrap();
        let _ = stream.set_read_timeout(self.opts.timeout);

        let path = if parsed_url.query().is_some() {
            format!("{}?{}", parsed_url.path(), parsed_url.query().unwrap())
        } else {
            parsed_url.path().to_string()
        };
        let uri = if path.is_empty() { "/".to_string() } else { path };

        let host_header = if let Some(h) = &self.opts.host {
            h.clone()
        } else if (is_https && port == 443) || (!is_https && port == 80) {
            host.clone()
        } else {
            format!("{}:{}", host, port)
        };

        let mut req_headers = BTreeMap::new();
        req_headers.insert("host".to_string(), host_header.clone());
        req_headers.insert("user-agent".to_string(), "oha/1.12.1".to_string());

        if let Some(accept) = &self.opts.accept_header {
            req_headers.insert("accept".to_string(), accept.clone());
        } else {
            req_headers.insert("accept".to_string(), "*/*".to_string());
        }

        if !self.opts.disable_compression {
            req_headers.insert("accept-encoding".to_string(), "gzip, compress, deflate, br".to_string());
        }

        if let Some(auth) = &self.opts.basic_auth {
            let encoded = base64_encode(auth.as_bytes());
            req_headers.insert("authorization".to_string(), format!("Basic {}", encoded));
        }

        let mut body_bytes: Option<Vec<u8>> = None;

        if let Some(b) = &self.opts.body_string {
            body_bytes = Some(b.as_bytes().to_vec());
        } else if let Some(p) = &self.opts.body_path {
            if let Ok(mut f) = File::open(p) {
                let mut v = Vec::new();
                let _ = f.read_to_end(&mut v);
                body_bytes = Some(v);
            }
        } else if let Some(p) = &self.opts.body_path_lines {
            if let Ok(f) = File::open(p) {
                use std::io::BufRead;
                let reader = std::io::BufReader::new(f);
                let lines: Vec<String> = reader.lines().filter_map(|l| l.ok()).collect();
                if !lines.is_empty() {
                    let mut rng = rand::thread_rng();
                    use rand::Rng;
                    let idx = rng.gen_range(0..lines.len());
                    body_bytes = Some(lines[idx].as_bytes().to_vec());
                }
            }
        } else if !self.opts.form.is_empty() {
            let boundary = format!("----formdata-oha-{}", random_hex(16));
            let mut form_body = Vec::new();
            for f in &self.opts.form {
                if let Some((name, val)) = f.split_once('=') {
                    if let Some(file_path) = val.strip_prefix('@') {
                        let path = Path::new(file_path);
                        let fname = path.file_name().and_then(|n| n.to_str()).unwrap_or("file");
                        let mut file_content = Vec::new();
                        if let Ok(mut file) = File::open(path) {
                            let _ = file.read_to_end(&mut file_content);
                        }
                        let part_hdr = format!(
                            "--{}\r\nContent-Disposition: form-data; name=\"{}\"; filename=\"{}\"\r\n\r\n",
                            boundary, name, fname
                        );
                        form_body.extend_from_slice(part_hdr.as_bytes());
                        form_body.extend_from_slice(&file_content);
                        form_body.extend_from_slice(b"\r\n");
                    } else {
                        let part_hdr = format!(
                            "--{}\r\nContent-Disposition: form-data; name=\"{}\"\r\n\r\n{}\r\n",
                            boundary, name, val
                        );
                        form_body.extend_from_slice(part_hdr.as_bytes());
                    }
                }
            }
            let end_boundary = format!("--{}--\r\n", boundary);
            form_body.extend_from_slice(end_boundary.as_bytes());

            req_headers.insert(
                "content-type".to_string(),
                format!("multipart/form-data; boundary={}", boundary),
            );
            body_bytes = Some(form_body);
        }

        if let Some(ct) = &self.opts.content_type {
            req_headers.insert("content-type".to_string(), ct.clone());
        }

        for h in &self.opts.headers {
            if let Some((k, v)) = h.split_once(':') {
                req_headers.insert(k.trim().to_lowercase(), v.trim().to_string());
            }
        }

        if let Some(b) = &body_bytes {
            req_headers.insert("content-length".to_string(), b.len().to_string());
        }

        if self.opts.disable_keepalive {
            req_headers.insert("connection".to_string(), "close".to_string());
        }

        let mut req_str = format!("{} {} HTTP/1.1\r\n", self.opts.method, uri);
        for (k, v) in &req_headers {
            req_str.push_str(&format!("{}: {}\r\n", k, v));
        }
        req_str.push_str("\r\n");

        if self.opts.debug {
            print_debug_request(&self.opts.method, &uri, &req_headers, body_bytes.as_deref());
        }

        let t_req_start = Instant::now();
        if let Err(e) = stream.write_all(req_str.as_bytes()) {
            *conn = None;
            let dur = start_time.elapsed();
            return RequestResult {
                start_time,
                start_offset,
                dns_lookup_duration,
                dns_dialup_duration,
                response_delay: Duration::ZERO,
                request_duration: dur,
                bytes: 0,
                status: Err(format!("{}", e)),
            };
        }

        if let Some(b) = &body_bytes {
            if let Err(e) = stream.write_all(b) {
                *conn = None;
                let dur = start_time.elapsed();
                return RequestResult {
                    start_time,
                    start_offset,
                    dns_lookup_duration,
                    dns_dialup_duration,
                    response_delay: Duration::ZERO,
                    request_duration: dur,
                    bytes: 0,
                    status: Err(format!("{}", e)),
                };
            }
        }

        let mut resp_header_bytes = Vec::new();
        let mut single_buf = [0u8; 1];
        let mut t_first_byte = None;

        loop {
            match stream.read(&mut single_buf) {
                Ok(1) => {
                    if t_first_byte.is_none() {
                        t_first_byte = Some(Instant::now());
                    }
                    resp_header_bytes.push(single_buf[0]);
                    if resp_header_bytes.ends_with(b"\r\n\r\n") {
                        break;
                    }
                }
                Ok(0) => break,
                Ok(_) => {}
                Err(e) => {
                    *conn = None;
                    let dur = start_time.elapsed();
                    return RequestResult {
                        start_time,
                        start_offset,
                        dns_lookup_duration,
                        dns_dialup_duration,
                        response_delay: Duration::ZERO,
                        request_duration: dur,
                        bytes: 0,
                        status: Err(format!("{}", e)),
                    };
                }
            }
        }

        let response_delay = t_first_byte.unwrap_or(Instant::now()).saturating_duration_since(t_req_start);

        let header_str = String::from_utf8_lossy(&resp_header_bytes);
        let mut lines = header_str.lines();
        let status_line = lines.next().unwrap_or("");

        let status_code: u16 = status_line
            .split_whitespace()
            .nth(1)
            .and_then(|s| s.parse().ok())
            .unwrap_or(200);

        let mut resp_headers = BTreeMap::new();
        for line in lines {
            if let Some((k, v)) = line.split_once(':') {
                resp_headers.insert(k.trim().to_lowercase(), v.trim().to_string());
            }
        }

        let content_length: Option<usize> = resp_headers.get("content-length").and_then(|v| v.parse().ok());
        let is_chunked = resp_headers.get("transfer-encoding").map(|v| v.contains("chunked")).unwrap_or(false);
        let is_gzipped = resp_headers.get("content-encoding").map(|v| v.contains("gzip")).unwrap_or(false);

        let mut body = Vec::new();

        if is_chunked {
            read_chunked_body(stream, &mut body);
        } else if let Some(len) = content_length {
            let mut remaining = len;
            let mut buf = [0u8; 4096];
            while remaining > 0 {
                let to_read = remaining.min(buf.len());
                match stream.read(&mut buf[..to_read]) {
                    Ok(0) => break,
                    Ok(n) => {
                        body.extend_from_slice(&buf[..n]);
                        remaining -= n;
                    }
                    Err(_) => break,
                }
            }
        } else {
            let mut buf = [0u8; 4096];
            loop {
                match stream.read(&mut buf) {
                    Ok(0) => break,
                    Ok(n) => body.extend_from_slice(&buf[..n]),
                    Err(_) => break,
                }
            }
        }

        let final_body = if is_gzipped {
            let mut decoder = GzDecoder::new(&body[..]);
            let mut decompressed = Vec::new();
            if decoder.read_to_end(&mut decompressed).is_ok() {
                decompressed
            } else {
                body.clone()
            }
        } else {
            body.clone()
        };

        let request_duration = start_time.elapsed();

        if self.opts.debug {
            print_debug_response(status_code, &resp_headers, &final_body);
        }

        if self.opts.disable_keepalive || resp_headers.get("connection").map(|v| v == "close").unwrap_or(false) {
            *conn = None;
        }

        RequestResult {
            start_time,
            start_offset,
            dns_lookup_duration,
            dns_dialup_duration,
            response_delay,
            request_duration,
            bytes: final_body.len(),
            status: Ok(status_code),
        }
    }
}

fn read_chunked_body(stream: &mut ConnectionStream, body: &mut Vec<u8>) {
    let mut single = [0u8; 1];
    loop {
        let mut line = Vec::new();
        loop {
            match stream.read(&mut single) {
                Ok(1) => {
                    line.push(single[0]);
                    if line.ends_with(b"\r\n") {
                        break;
                    }
                }
                _ => return,
            }
        }
        let line_str = String::from_utf8_lossy(&line);
        let hex_str = line_str.trim().split(';').next().unwrap_or("");
        let chunk_size = match usize::from_str_radix(hex_str, 16) {
            Ok(s) => s,
            Err(_) => return,
        };
        if chunk_size == 0 {
            let mut trailer = [0u8; 1];
            while let Ok(1) = stream.read(&mut trailer) {
                if body.ends_with(b"\r\n\r\n") {
                    break;
                }
            }
            break;
        }
        let mut remaining = chunk_size;
        let mut buf = [0u8; 4096];
        while remaining > 0 {
            let to_read = remaining.min(buf.len());
            match stream.read(&mut buf[..to_read]) {
                Ok(0) => break,
                Ok(n) => {
                    body.extend_from_slice(&buf[..n]);
                    remaining -= n;
                }
                Err(_) => break,
            }
        }
        let _ = stream.read(&mut [0u8; 2]);
    }
}

fn base64_encode(bytes: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut res = String::new();
    let mut i = 0;
    while i < bytes.len() {
        let b0 = bytes[i];
        let b1 = if i + 1 < bytes.len() { bytes[i + 1] } else { 0 };
        let b2 = if i + 2 < bytes.len() { bytes[i + 2] } else { 0 };

        let triple = ((b0 as u32) << 16) | ((b1 as u32) << 8) | (b2 as u32);

        res.push(CHARS[((triple >> 18) & 0x3F) as usize] as char);
        res.push(CHARS[((triple >> 12) & 0x3F) as usize] as char);

        if i + 1 < bytes.len() {
            res.push(CHARS[((triple >> 6) & 0x3F) as usize] as char);
        } else {
            res.push('=');
        }

        if i + 2 < bytes.len() {
            res.push(CHARS[(triple & 0x3F) as usize] as char);
        } else {
            res.push('=');
        }

        i += 3;
    }
    res
}

fn random_hex(len: usize) -> String {
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let mut s = String::new();
    for _ in 0..len {
        s.push_str(&format!("{:02x}", rng.gen::<u8>()));
    }
    s
}

fn print_debug_request(method: &str, uri: &str, headers: &BTreeMap<String, String>, body: Option<&[u8]>) {
    println!("Request {{");
    println!("    method: {},", method);
    println!("    uri: {},", uri);
    println!("    version: HTTP/1.1,");
    println!("    headers: {{");
    for (k, v) in headers {
        println!("        \"{}\": \"{}\",", k, v);
    }
    println!("    }},");
    println!("    body: Full {{");
    if let Some(b) = body {
        println!("        data: Some(");
        println!("            b\"{}\",", String::from_utf8_lossy(b));
        println!("        ),");
    } else {
        println!("        data: None,");
    }
    println!("    }},");
    println!("}}");
}

fn print_debug_response(status: u16, headers: &BTreeMap<String, String>, body: &[u8]) {
    println!("Response {{");
    println!("    status: {},", status);
    println!("    version: HTTP/1.0,");
    println!("    headers: {{");
    for (k, v) in headers {
        println!("        \"{}\": \"{}\",", k, v);
    }
    println!("    }},");
    println!("    body: b\"{}\",", String::from_utf8_lossy(body));
    println!("}}");
}
